export const FIELD_TOTALS = {
  starters: 1564,
  finishers: 1060,
  finishRate: 67.8,
};

const byStation = new Map(CUTOFFS.map((c) => [c.station, c]));

/** Official cutoff for a station, by its official name. */
export function cutoffFor(name) {
  return byStation.get(name) || null;
}

/** Every finish time across all six years, sorted. */
export const ALL_TIMES = YEARS.flatMap((y) => y.times).sort((a, b) => a - b);

/** What fraction of finishers came in at or under `hours`. */
export function percentileOf(hours) {
  if (!ALL_TIMES.length) return null;
  const n = ALL_TIMES.filter((t) => t <= hours).length;
  return Math.round((n / ALL_TIMES.length) * 100);
}

/** The p-th percentile finish time, in hours. */
export function timeAtPercentile(p) {
  if (!ALL_TIMES.length) return null;
  const i = Math.min(ALL_TIMES.length - 1, Math.max(0, Math.round((p / 100) * ALL_TIMES.length) - 1));
  return ALL_TIMES[i];
}
